function populateLargeModelControls(){const dl=document.getElementById('node-search-options');if(dl){const currentCount=dl.dataset.count?Number(dl.dataset.count):0;if(currentCount!==currentModelData.nodes.length){dl.innerHTML=currentModelData.nodes.map(n=>`<option value="${esc(n.label)}">${esc(n.type)}${n.metadata?.cmdbClass?' / '+esc(n.metadata.cmdbClass):''}</option>`).join('');dl.dataset.count=String(currentModelData.nodes.length)}}const rel=document.getElementById('relationship-filter');if(rel){const labels=['all',...Array.from(new Set(currentModelData.edges.map(e=>e.label||e.relationship).filter(Boolean))).sort()];const sig=labels.join('|');if(rel.dataset.labels!==sig){rel.innerHTML=labels.map(l=>`<option value="${esc(l)}" ${l===activeRelationshipFilter?'selected':''}>${l==='all'?'All':esc(l)}</option>`).join('');rel.dataset.labels=sig}else rel.value=activeRelationshipFilter}const hops=document.getElementById('focus-hop-count');if(hops)hops.value=String(focusHopCount);const cm=document.getElementById('cluster-mode');if(cm)cm.value=clusterMode;const pm=document.getElementById('performance-mode');if(pm)pm.value=performanceMode;const lm=document.getElementById('learning-mode');if(lm)lm.value=learningMode?'on':'off';const lb=document.getElementById('learn-menu-btn');if(lb){lb.innerHTML=learningMode?'Learn: On &#9662;':'Learn &#9662;';lb.style.background=learningMode?'#0f766e':''}const vb=document.getElementById('view-menu-btn');if(vb){const filtered=activeViewMode!=='full'||activeRelationshipFilter!=='all'||clusterMode!=='off';vb.innerHTML=filtered?'View: Filtered &#9662;':'View &#9662;';vb.style.background=filtered?'#0f766e':''}}
