function openInspectorPanel(){const panel=document.getElementById('inspector-panel');if(!panel)return;panel.classList.remove('collapsed');const btn=document.getElementById('inspector-toggle');if(btn)btn.textContent='Hide'}
function renderInspector(html){const body=document.getElementById('inspector-body');if(!body)return;openInspectorPanel();body.innerHTML=html}
function nodeRelationshipRows(nodeId){return currentModelData.edges.map((e,i)=>Object.assign({_index:i,label:e.label||e.relationship},e)).filter(e=>e.from===nodeId||e.to===nodeId)}
function countBy(items,fn){return items.reduce((acc,item)=>{const key=fn(item)||'Unknown';acc[key]=(acc[key]||0)+1;return acc},{})}
function countsMarkup(counts){const keys=Object.keys(counts).sort();return keys.length?keys.map(k=>'<div class="inspector-count"><span>'+inspectorEsc(k)+'</span><strong>'+counts[k]+'</strong></div>').join(''):'<div class="inspector-muted">None</div>'}
function connectionListMarkup(edges,nodeId,direction){const rows=edges.filter(e=>direction==='out'?e.from===nodeId:e.to===nodeId).slice(0,16);if(!rows.length)return '<div class="inspector-muted">None</div>';return rows.map(e=>{const other=getNode(direction==='out'?e.to:e.from);const arrow=direction==='out'?'→':'←';const otherId=other?other.id:'';return '<button class="inspector-link" type="button" onclick="showNodeInspector(\''+inspectorEsc(otherId)+'\')"><span>'+inspectorEsc(e.label||e.relationship)+'</span> '+arrow+' '+inspectorEsc(other?other.label:'Unknown node')+'</button>'}).join('')}
function possibleRelationshipsMarkup(nodeType){const rules=window.CSDM_SCHEMA.getRulesFromType(nodeType);if(!rules.length)return '<div class="inspector-muted">No outgoing relationship types are defined for this class.</div>';if(isInfraType(nodeType)){const labels=[...new Set(rules.map(r=>r.label))],targets=[...new Set(rules.map(r=>r.toType))];return '<div class="inspector-muted">Infrastructure classes connect freely. From here, any of these relationship types is valid:</div><div class="inspector-tags">'+labels.map(l=>'<span class="inspector-tag">'+inspectorEsc(l)+'</span>').join('')+'</div><div class="inspector-muted" style="margin-top:6px">...to any of '+targets.length+' infrastructure classes.</div>'}const byLabel={};rules.forEach(r=>{(byLabel[r.label]=byLabel[r.label]||[]).push(r.toType)});return Object.entries(byLabel).map(([label,targets])=>'<div class="inspector-rel-group"><div class="inspector-rel-label">'+inspectorEsc(label)+'</div><div class="inspector-rel-targets">'+targets.map(inspectorEsc).join(', ')+'</div></div>').join('')}
function copyInspectorJson(kind,id){let obj=null;if(kind==='node')obj=getNode(id);else if(kind==='edge')obj=currentModelData.edges[Number(id)];else if(kind==='cluster')obj=getClusterSummary(id);if(!obj)return alert('Nothing to copy.');const txt=JSON.stringify(obj,null,2);if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(txt).then(()=>alert('Copied JSON to clipboard.')).catch(()=>prompt('Copy JSON:',txt));else prompt('Copy JSON:',txt)}
function inspectorFocusNode(id,hops){selectedNodeId=id;focusSelectedNode(hops)}
function inspectorShowRelationship(label){activeRelationshipFilter=label||'all';const rel=document.getElementById('relationship-filter');if(rel)rel.value=activeRelationshipFilter;renderGraph();updateStatusBar()}
function inspectorShowDomain(domain){const ids=currentModelData.nodes.filter(n=>(n.domain||'Unknown')===domain).map(n=>n.id);const visible=new Set(ids);const edges=currentModelData.edges.filter(e=>visible.has(e.from)&&visible.has(e.to));renderInspector('<div class="inspector-title">Domain</div><h3>'+inspectorEsc(domain)+'</h3><div class="inspector-grid two"><div><label>Nodes</label><strong>'+ids.length+'</strong></div><div><label>Internal relationships</label><strong>'+edges.length+'</strong></div></div><div class="inspector-actions"><button type="button" onclick="setClusterMode(\'domain\')">Cluster by Domain</button></div>')}
function showNodeInspector(nodeId){const n=getNode(nodeId);if(!n)return;selectedNodeId=nodeId;const edges=nodeRelationshipRows(nodeId);const inbound=edges.filter(e=>e.to===nodeId);const outbound=edges.filter(e=>e.from===nodeId);const counts=countBy(edges,e=>e.label||e.relationship);let meta='<div><label>Type (EA)</label><span>'+inspectorEsc(n.type)+'</span></div>'+(serviceNowClass(n.type)?'<div><label>ServiceNow class</label><span>'+inspectorEsc(serviceNowClass(n.type))+'</span></div>':'')+'<div><label>ID</label><code>'+inspectorEsc(n.id)+'</code></div><div><label>Domain</label><span>'+inspectorEsc(n.domain||'Unknown')+'</span></div>';if(n.metadata&&n.metadata.cmdbClass)meta+='<div><label>CMDB Class</label><span>'+inspectorEsc(n.metadata.cmdbClass)+'</span></div>';window.CSDM_SCHEMA.getMetadataFields(n.type).filter(f=>f.key!=='description').forEach(f=>{const val=n.metadata&&n.metadata[f.key];meta+='<div><label>'+inspectorEsc(f.label)+'</label><span>'+inspectorEsc(val||'—')+'</span></div>'});renderInspector('<div class="inspector-title">Selected Node</div><h3>'+inspectorEsc(n.label)+'</h3><div class="inspector-meta">'+meta+'</div><p class="inspector-description">'+inspectorEsc(n.metadata&&n.metadata.description?n.metadata.description:'No description provided.')+'</p><div class="inspector-grid"><div><label>Inbound</label><strong>'+inbound.length+'</strong></div><div><label>Outbound</label><strong>'+outbound.length+'</strong></div><div><label>Total</label><strong>'+edges.length+'</strong></div></div><h4>Relationship Mix</h4>'+countsMarkup(counts)+'<h4>Outbound Connections</h4>'+connectionListMarkup(edges,nodeId,'out')+'<h4>Inbound Connections</h4>'+connectionListMarkup(edges,nodeId,'in')+'<h4>Possible Relationships From Here</h4>'+possibleRelationshipsMarkup(n.type)+'<div class="inspector-actions"><button type="button" onclick="openWhyNodeDialog(\''+inspectorEsc(n.id)+'\')">Why it matters</button><button type="button" onclick="openImpactDialog(\''+inspectorEsc(n.id)+'\')">Impact Analysis</button><button type="button" onclick="inspectorFocusNode(\''+inspectorEsc(n.id)+'\',1)">Focus 1-hop</button><button type="button" onclick="inspectorFocusNode(\''+inspectorEsc(n.id)+'\',2)">Focus 2-hop</button><button type="button" onclick="inspectorShowDomain(\''+inspectorEsc(n.domain||'Unknown')+'\')">Show Domain</button><button type="button" onclick="copyInspectorJson(\'node\',\''+inspectorEsc(n.id)+'\')">Copy Node JSON</button></div>')}
function showEdgeInspector(edgeId,visibleEdge){const original=currentModelData.edges[Number(edgeId)];const e=original||visibleEdge;if(!e)return;const from=getNode(e.from),to=getNode(e.to),label=e.label||e.relationship||'';const md=e.metadata||{};let meta='<div><label>From</label><button class="inspector-link" type="button" onclick="showNodeInspector(\''+inspectorEsc(e.from)+'\')">'+inspectorEsc(from?from.label:e.from)+'</button></div><div><label>To</label><button class="inspector-link" type="button" onclick="showNodeInspector(\''+inspectorEsc(e.to)+'\')">'+inspectorEsc(to?to.label:e.to)+'</button></div><div><label>Label (EA)</label><span>'+inspectorEsc(label)+'</span></div>'+(serviceNowRel(label)?'<div><label>ServiceNow relationship</label><span>'+inspectorEsc(serviceNowRel(label))+'</span></div>':'');if(md.sourceRelationship)meta+='<div><label>Source relationship</label><span>'+inspectorEsc(md.sourceRelationship)+'</span></div>';if(md.sourceBaseClass)meta+='<div><label>Source base class</label><span>'+inspectorEsc(md.sourceBaseClass)+'</span></div>';if(md.sourceDependentClass)meta+='<div><label>Source dependent class</label><span>'+inspectorEsc(md.sourceDependentClass)+'</span></div>';renderInspector('<div class="inspector-title">Selected Relationship</div><h3>'+inspectorEsc(label)+'</h3><div class="inspector-meta">'+meta+'</div><div class="inspector-actions"><button type="button" onclick="inspectorShowRelationship(\''+inspectorEsc(label)+'\')">Show Only This Relationship</button><button type="button" onclick="copyInspectorJson(\'edge\',\''+Number(edgeId)+'\')">Copy Edge JSON</button></div>')}
function getClusterSummary(domain){const members=currentModelData.nodes.filter(n=>(n.domain||'Unknown')===domain&&!['Business Capability','Business Application','Application Service','Business Service','Service Offering'].includes(n.type));const ids=new Set(members.map(n=>n.id));const touching=currentModelData.edges.filter(e=>ids.has(e.from)||ids.has(e.to));return{domain:domain,nodeCount:members.length,relationshipCount:touching.length,topClasses:countBy(members,n=>(n.metadata&&n.metadata.cmdbClass)||n.type),relationships:countBy(touching,e=>e.label||e.relationship)}}
function showClusterInspector(domain){const summary=getClusterSummary(domain);const expanded=expandedClusters&&expandedClusters.has(domain);const topClasses=Object.entries(summary.topClasses).sort((a,b)=>b[1]-a[1]).slice(0,10);const cls=topClasses.length?topClasses.map(([k,v])=>'<div class="inspector-count"><span>'+inspectorEsc(k)+'</span><strong>'+v+'</strong></div>').join(''):'<div class="inspector-muted">None</div>';renderInspector('<div class="inspector-title">Domain Cluster</div><h3>'+inspectorEsc(domain)+'</h3><div class="inspector-grid"><div><label>Nodes</label><strong>'+summary.nodeCount+'</strong></div><div><label>Touching relationships</label><strong>'+summary.relationshipCount+'</strong></div><div><label>Status</label><strong>'+(expanded?'Expanded':'Collapsed')+'</strong></div></div><h4>Top CMDB Classes</h4>'+cls+'<h4>Relationship Mix</h4>'+countsMarkup(summary.relationships)+'<div class="inspector-actions"><button type="button" onclick="toggleDomainCluster(\''+inspectorEsc(domain)+'\')">'+(expanded?'Collapse':'Expand')+' Cluster</button><button type="button" onclick="inspectorShowDomain(\''+inspectorEsc(domain)+'\')">Show Domain Summary</button><button type="button" onclick="copyInspectorJson(\'cluster\',\''+inspectorEsc(domain)+'\')">Copy Cluster Summary</button></div>')}

function buildStatsText(){const fg=getFilteredGraph();const rel=activeRelationshipFilter==='all'?'All':activeRelationshipFilter,cl=clusterMode==='off'?'Off':`Domain (${expandedClusters.size} expanded)`,perf=performanceMode==='auto'?(lastRenderedGraphStats.lightweight?'Auto/Fast':'Auto/Detail'):performanceMode;return `Model: ${currentModelData.seedModel||'Custom'}\nView Mode: ${viewLabel(activeViewMode)}\nRelationship Filter: ${rel}\nCluster: ${cl}\nPerformance: ${perf}\nShowing: ${fg.nodes.length}/${currentModelData.nodes.length} nodes, ${fg.edges.length}/${currentModelData.edges.length} relationships\nUnsaved changes: ${hasUnsavedChanges()?'Yes':'No'}\nUndo available: ${undoStack.length}\nRedo available: ${redoStack.length}\nLearning Mode: ${learningMode?`On (${learningStats.correct}/${learningStats.attempts} correct this session)`:'Off'}`}function openStatsDialog(){document.getElementById('modal-title').textContent='Diagram Stats';document.getElementById('modal-body').innerHTML=`<div class="readonly" style="white-space:pre-wrap">${esc(buildStatsText())}</div><div class="actions"><button onclick="closeDialog()">OK</button></div>`;document.getElementById('modal-backdrop').classList.remove('hidden')}function classTierBadge(type){const t=classTier(type),b=t==='stock'?['Stock CSDM','#15803d']:t==='extended-usable'?['Extended','#1d4ed8']:['Unmapped'+(allowSandboxClasses?'':' · hidden'),'#6b7280'];return `<span style="display:inline-block;padding:2px 7px;border-radius:9px;background:${b[1]};color:#fff;font-size:10px;font-weight:700;white-space:nowrap">${b[0]}</span>`}
function openClassesDialog(){const types=Object.keys(window.CSDM_SCHEMA.nodeTypes),nStock=types.filter(isStockCsdm).length,nUsable=types.filter(t=>!isStockCsdm(t)&&SERVICENOW_CLASS[t]).length,nHidden=types.filter(t=>!SERVICENOW_CLASS[t]).length;const rows=Object.entries(window.CSDM_SCHEMA.nodeTypes).sort((a,b)=>a[1].level-b[1].level).map(([name,v])=>`<tr><td>${v.level}</td><td><strong>${esc(name)}</strong></td><td>${classTierBadge(name)}</td><td>${esc(serviceNowClass(name)||'—')}</td><td>${esc(v.domain)}</td><td>${esc(v.description||'')}</td></tr>`).join('');document.getElementById('modal-title').textContent='Node Classes';document.getElementById('modal-body').innerHTML=`<p class="muted">${types.length} classes — <strong>${nStock}</strong> stock CSDM (the framework itself), <strong>${nUsable}</strong> extended infrastructure (real ServiceNow CMDB classes the services resolve down onto)${nHidden?`, <strong>${nHidden}</strong> unmapped (${allowSandboxClasses?'shown in builders':'hidden from builders'})`:''}. Ordered by layout level (business intent at the top, deep infrastructure at the bottom). The ServiceNow column shows the corresponding CSDM class / table.</p>${nHidden?`<label style="display:flex;align-items:center;gap:8px;margin:6px 0 12px;font-size:13px;font-weight:600"><input type="checkbox" ${allowSandboxClasses?'checked':''} onchange="setAllowSandboxClasses(this.checked)"> Allow the ${nHidden} unmapped classes in the builders</label>`:''}<table class="classes-table"><thead><tr><th>Level</th><th>Class (EA)</th><th>Status</th><th>ServiceNow</th><th>Domain</th><th>Description</th></tr></thead><tbody>${rows}</tbody></table><div class="actions"><button onclick="closeDialog()">OK</button></div>`;document.getElementById('modal-backdrop').classList.remove('hidden')}function referenceChip(t){const col=(domainMap[t]||{color:'#64748b'}).color;return `<div style="background:${col};color:#fff;border-radius:8px;padding:7px 6px;font-weight:700;font-size:11px">${esc(t)}</div>`}
function openBusinessReferenceDialog(){const S=window.CSDM_SCHEMA,classes=['Business Capability','Business Application','Application Service','Business Service','Service Offering'],laneName=t=>laneFor(t)===-1?'Design & Plan':laneFor(t)===1?'Sell & Consume':'Convergence';const classRows=classes.map(t=>`<tr><td><strong>${esc(t)}</strong></td><td>${esc(laneName(t))}</td><td>${esc((S.nodeTypes[t]||{}).description||'')}</td></tr>`).join('');const rels=[['Business Application','Provides','Business Capability'],['Business Application','Instantiates','Application Service'],['Business Service','Offers','Service Offering'],['Service Offering','Depends on','Application Service']];const relRows=rels.map(([f,l,t])=>{const r=S.getAllowedRelationship(f,t,l);return `<tr><td><strong>${esc(f)}</strong> &mdash;${esc(l)}&rarr; <strong>${esc(t)}</strong></td><td>${esc(serviceNowRel(l)||'—')}</td><td>${esc(r?r.explanation:'')}</td></tr>`}).join('');document.getElementById('modal-title').textContent='Business Layer Reference';document.getElementById('modal-body').innerHTML=`<p class="muted">The top of a CSDM model is two parallel paths that converge on the Application Service &mdash; the running thing that owns infrastructure. Use this as a template when you set up your own business components.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;text-align:center;align-items:center;margin:10px 0"><div style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase">Design &amp; Plan</div><div style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase">Sell &amp; Consume</div>${referenceChip('Business Capability')}${referenceChip('Business Service')}<div class="muted">&#9650; Provides</div><div class="muted">&#9660; Offers</div>${referenceChip('Business Application')}${referenceChip('Service Offering')}</div><div class="muted" style="text-align:center;margin:2px 0">Instantiates &#8600;&nbsp;&nbsp;&#8601; Depends on</div><div style="max-width:220px;margin:0 auto 6px">${referenceChip('Application Service')}</div><div class="muted" style="text-align:center">&#9660; Depends on / Runs on &rarr; Infrastructure</div><h3 style="font-size:14px;margin:10px 0 6px">Classes</h3><table class="classes-table"><thead><tr><th>Class</th><th>Lane</th><th>What it is</th></tr></thead><tbody>${classRows}</tbody></table><h3 style="font-size:14px;margin:12px 0 6px">Relationships</h3><table class="classes-table"><thead><tr><th>Relationship (EA)</th><th>ServiceNow</th><th>Meaning</th></tr></thead><tbody>${relRows}</tbody></table><div class="explain-box" style="margin-top:10px"><strong>Environments:</strong> give each environment (Prod, Stage, Dev) its own Application Service instantiated from the same Business Application, so an outage in one can't make another look degraded. Add a Service Offering only where the environment is actually consumed under a commitment. Tip: right-click an Application Service &rarr; <em>Add Environment</em> to clone its infrastructure tree.</div><div class="actions"><button class="secondary" onclick="loadReferenceExample()">Load Full Example Model</button><button onclick="closeDialog()">OK</button></div>`;document.getElementById('modal-backdrop').classList.remove('hidden')}
async function loadReferenceExample(){if(hasUnsavedChanges()&&!confirm('Loading the reference example will replace your current working model. Continue?'))return;try{const r=await fetch('/api/csdm/load',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file:'csdmData.reference-example.json'})}),p=await r.json().catch(()=>({}));if(!r.ok)throw new Error(p.error||'Unable to load the reference example.');try{localStorage.setItem('csdm.currentModelName','CSDM Reference Example')}catch(_){}alert('Reference example loaded. The page will refresh.');window.location.reload()}catch(err){alert(err.message||'Unable to load the reference example.')}}
function updateStatusBar(){const s=document.getElementById('status-text');if(!s)return;if(s.textContent==='Loading...')s.textContent='';populateLargeModelControls();const buttons=document.querySelectorAll('#status-bar button');const undo=[...buttons].find(b=>b.textContent.trim()==='Undo'),redo=[...buttons].find(b=>b.textContent.trim()==='Redo'),save=document.getElementById('status-save-model')||[...buttons].find(b=>b.textContent.trim()==='Save'),discard=[...buttons].find(b=>b.textContent.trim()==='Discard');if(undo)undo.disabled=!undoStack.length;if(redo)redo.disabled=!redoStack.length;if(save)save.disabled=!hasUnsavedChanges();if(discard)discard.disabled=!hasUnsavedChanges();if(window.CSDM_UPDATE_MODEL_NAME_DISPLAY)window.CSDM_UPDATE_MODEL_NAME_DISPLAY()}let lineageHighlight=null;
function buildAdjacency(byId){const adj=new Map();byId.forEach((_,id)=>adj.set(id,[]));currentModelData.edges.forEach(e=>{if(byId.has(e.from)&&byId.has(e.to)){adj.get(e.from).push(e.to);adj.get(e.to).push(e.from)}});return adj}
function traceHighlight(rootId,mode){const byId=new Map(currentModelData.nodes.map(n=>[n.id,n]));if(!byId.has(rootId))return null;const adj=buildAdjacency(byId),lvl=id=>((domainMap[byId.get(id).type]||{level:5}).level),set=new Set([rootId]);if(mode==='vertical'){const walk=dir=>{const st=[rootId];while(st.length){const id=st.pop(),L=lvl(id);adj.get(id).forEach(o=>{const ol=lvl(o);if((dir<0?ol<L:ol>L)&&!set.has(o)){set.add(o);st.push(o)}})}};walk(-1);walk(1)}else{const st=[rootId];while(st.length){const id=st.pop();adj.get(id).forEach(o=>{if(!set.has(o)){set.add(o);st.push(o)}})}}const edges=[];currentModelData.edges.forEach((e,i)=>{if(set.has(e.from)&&set.has(e.to)&&(mode!=='vertical'||lvl(e.from)!==lvl(e.to)))edges.push(i)});return{nodes:[...set],edges}}
function highlightLineage(nodeId,mode){const h=traceHighlight(nodeId,mode||'connected');if(!h)return;lineageHighlight=h;selectedNodeId=nodeId;renderGraph(h)}
function clearLineageHighlight(){const had=lineageHighlight||failureSim;lineageHighlight=null;failureSim=null;stopFailureCostTicker();const b=document.getElementById('failure-banner');if(b)b.remove();hideMenus();closeBarMenus();if(had)renderGraph()}
let failureSim=null;
function simulateFailure(nodeId){const rn=getNode(nodeId);if(rn&&isNonOperational(rn.type))return alert(`${rn.type} is a design/business artifact, not an operational CI, so it can't fail directly. Simulate a failure on the Application Service or the infrastructure beneath it instead.`);const cas=computeCascade(nodeId);if(!cas)return;lineageHighlight=null;const affNodes=[...cas.affected].map(id=>getNode(id)).filter(Boolean),revPerHour=affectedRevenuePerHour(affNodes),full=computeImpact(nodeId),wouldBe=full?affectedRevenuePerHour(full.affected):0;failureSim={failedId:nodeId,affected:cas.affected,protectedNodes:cas.protectedNodes,contained:cas.contained,revenuePerHour:revPerHour,wouldBeRevenue:wouldBe,startTime:Date.now()};selectedNodeId=nodeId;renderGraph();showFailureBanner(cas);startFailureCostTicker();if(networkInstance)try{networkInstance.focus(nodeId,{scale:networkInstance.getScale(),animation:{duration:250}})}catch(_){}}
function showFailureBanner(cas){const meta=n=>n.metadata||{},root=cas.root,affectedNodes=[...cas.affected].map(id=>getNode(id)).filter(Boolean),slas=affectedNodes.filter(n=>n.type==='Service Offering'&&meta(n).availabilityTarget),crit=affectedNodes.filter(n=>n.type==='Business Capability'&&/Critical/.test(meta(n).criticality||''));let b=document.getElementById('failure-banner');if(!b){b=document.createElement('div');b.id='failure-banner';document.body.appendChild(b)}let parts;if(cas.contained){parts=[`<strong>FAILURE ABSORBED</strong> &mdash; ${esc(root.label)} is redundant (${esc(meta(root).redundancy)})`,`a single failure is tolerated &mdash; no business impact`]}else{parts=[`<strong>FAILURE SIMULATION</strong> &mdash; ${esc(root.label)} is down`,`<strong>${cas.affected.size}</strong> component(s) impacted`];if(slas.length)parts.push(`SLAs at risk: ${slas.map(o=>esc(o.label)+' ('+esc(meta(o).availabilityTarget)+')').join(', ')}`);if(crit.length)parts.push(`critical: ${crit.map(c=>esc(c.label)).join(', ')}`);if(cas.protectedNodes.size)parts.push(`${cas.protectedNodes.size} protected by redundancy`)}const whatif=supportsRedundancy(root.type)?`<button class="fb-whatif" onclick="whatIfToggleRedundancy('${esc(root.id)}')">${isResilient(root)?'What-if: make single-instance':'What-if: add redundancy'}</button>`:'';let costHtml='';if(cas.contained){if(failureSim&&failureSim.wouldBeRevenue>0)costHtml=`<div class="fb-cost fb-cost-saved">Redundancy is saving <strong>${formatMoney(failureSim.wouldBeRevenue)}/hr</strong></div>`}else if(failureSim&&failureSim.revenuePerHour>0)costHtml=`<div class="fb-cost">Revenue at risk <strong>${formatMoney(failureSim.revenuePerHour)}/hr</strong> &middot; lost so far <strong id="fb-lost">$0</strong></div>`;const rediscover=canReDiscover(root.id)?`<button class="fb-rediscover" onclick="reRunDiscovery('${esc(root.id)}')">Re-run Discovery</button>`:'';b.className=cas.contained?'fb-contained':'';b.innerHTML=`<div class="fb-text">${parts.join(' &nbsp;|&nbsp; ')}</div>${costHtml}${rediscover}${whatif}<button onclick="clearLineageHighlight()">Clear</button>`}
function whatIfToggleRedundancy(nodeId){const n=getNode(nodeId);if(!n||!supportsRedundancy(n.type))return;const cur=n.metadata&&n.metadata.redundancy,next=(cur&&cur!=='Single instance')?'Single instance':'Redundant pair';markChange(`What-if: ${n.label} redundancy → ${next}`,()=>{n.metadata=n.metadata||{};n.metadata.redundancy=next});simulateFailure(nodeId)}
function getHostVMs(hostId){return currentModelData.edges.filter(e=>e.label==='Runs on'&&e.to===hostId&&getNode(e.from)&&getNode(e.from).type==='VM').map(e=>e.from)}
function getHostCluster(hostId){const e=currentModelData.edges.find(x=>x.label==='Contains'&&x.to===hostId&&getNode(x.from)&&getNode(x.from).type==='Virtualization Cluster');return e?e.from:null}
function getSurvivingHost(clusterId,failedHostId){const e=currentModelData.edges.find(x=>x.label==='Contains'&&x.from===clusterId&&x.to!==failedHostId&&getNode(x.to)&&getNode(x.to).type==='Compute Node');return e?e.to:null}
function canReDiscover(hostId){const n=getNode(hostId);if(!n||n.type!=='Compute Node')return false;if(!getHostVMs(hostId).length)return false;const cl=getHostCluster(hostId);return !!(cl&&getSurvivingHost(cl,hostId))}
function reRunDiscovery(hostId){const host=getNode(hostId);if(!host)return;const vms=getHostVMs(hostId),cl=getHostCluster(hostId),survivor=cl?getSurvivingHost(cl,hostId):null;if(!vms.length||!survivor)return alert('No VMs to migrate, or no surviving host in the cluster.');const survivorNode=getNode(survivor);markChange(`Re-discovery: migrate ${vms.length} VM(s) from ${host.label} to ${survivorNode.label}`,()=>{const sp=(survivorNode.metadata&&survivorNode.metadata.position)||{x:0,y:0};vms.forEach((vmId,i)=>{currentModelData.edges.forEach(e=>{if(e.label==='Runs on'&&e.from===vmId&&e.to===hostId)e.to=survivor});const vm=getNode(vmId);if(vm){vm.metadata=vm.metadata||{};vm.metadata.position={x:Math.round(sp.x+(i-(vms.length-1)/2)*120),y:sp.y+170}}})});failureSim=null;stopFailureCostTicker();const b=document.getElementById('failure-banner');if(b)b.remove();renderGraph();alert(`Re-discovery complete: ${vms.length} VM(s) migrated from ${host.label} to ${survivorNode.label}. Service Mapping (top-down discovery) re-ran and the CMDB now reflects the new placement — infrastructure is dynamic, and the model is only accurate once discovery runs again.`)}
