let tourIndex=0;
function startTour(){tourIndex=0;renderTourStep()}
function endTour(){try{localStorage.setItem('csdm.tourSeen','1')}catch(_){}['tour-backdrop','tour-card'].forEach(id=>{const el=document.getElementById(id);if(el)el.remove()})}
function tourNext(){if(tourIndex>=TOUR_STEPS.length-1)return endTour();tourIndex++;renderTourStep()}
function tourPrev(){if(tourIndex>0){tourIndex--;renderTourStep()}}
function renderTourStep(){const step=TOUR_STEPS[tourIndex];let bd=document.getElementById('tour-backdrop');if(!bd){bd=document.createElement('div');bd.id='tour-backdrop';document.body.appendChild(bd)}let card=document.getElementById('tour-card');if(!card){card=document.createElement('div');card.id='tour-card';document.body.appendChild(card)}const target=step.target?document.querySelector(step.target):null;if(target){const r=target.getBoundingClientRect();bd.classList.remove('tour-full');bd.style.top=(r.top-6)+'px';bd.style.left=(r.left-6)+'px';bd.style.width=(r.width+12)+'px';bd.style.height=(r.height+12)+'px'}else{bd.classList.add('tour-full');bd.style.top=bd.style.left=bd.style.width=bd.style.height=''}card.innerHTML=`<div class="tour-count">Step ${tourIndex+1} of ${TOUR_STEPS.length}</div><h3>${esc(step.title)}</h3><div class="tour-body">${step.body}</div><div class="tour-actions"><button class="tour-skip" onclick="endTour()">Skip</button><div class="tour-nav"><button ${tourIndex===0?'disabled':''} onclick="tourPrev()">Back</button><button class="tour-primary" onclick="tourNext()">${tourIndex===TOUR_STEPS.length-1?'Done':'Next'}</button></div></div>`;const cr=card.getBoundingClientRect();if(target){const r=target.getBoundingClientRect(),spaceBelow=window.innerHeight-r.bottom;let top=spaceBelow>cr.height+24?r.bottom+14:Math.max(12,r.top-cr.height-14),left=Math.min(Math.max(12,r.left),window.innerWidth-cr.width-12);card.style.top=top+'px';card.style.left=left+'px';card.style.transform=''}else{card.style.top='50%';card.style.left='50%';card.style.transform='translate(-50%,-50%)'}}
function maybeAutoTour(){let seen=false;try{seen=!!localStorage.getItem('csdm.tourSeen')}catch(_){}if(!seen)setTimeout(startTour,900)}
loadSandbox();maybeAutoTour();
